const UPDATE_TUTOR={
 intro:B('Follow the highlighted line with the tutor. On line 2, reading and calculating happen before the stored value changes.','Ikuti baris yang diserlahkan bersama tutor. Pada baris 2, membaca dan mengira berlaku sebelum nilai tersimpan berubah.','跟随指导阅读高亮行。第2行先读取、再计算，最后才改变存储的值。'),
 back:B('Previous step','Langkah sebelumnya','上一步'),replay:B('Replay the explanation','Ulang penerangan','重新演示'),
 stored:B('The value currently stored','Nilai yang disimpan sekarang','当前存储的值'),
 steps:[
 {line:1,value:'1',focus:'whole',title:B('Line 1 · Store the first value','Baris 1 · Simpan nilai pertama','第1行 · 存储初始值'),note:B('Start with warning_count = 1. The = sign assigns the value on the right to the name on the left. We have now stored the integer 1 in warning_count. Nothing is printed.','Mulakan dengan warning_count = 1. Tanda = menugaskan nilai di sebelah kanan kepada nama di sebelah kiri. Kini integer 1 disimpan dalam warning_count. Tiada output dicetak.','从 warning_count = 1 开始。= 把右边的值赋给左边的名称。现在 warning_count 中存储了整数 1，没有打印任何输出。'),calculation:'warning_count ← 1',next:B('Read line 2','Baca baris 2','读取第2行')},
 {line:2,value:'1',focus:'read',title:B('Line 2 · Read the old value','Baris 2 · Baca nilai lama','第2行 · 读取旧值'),note:B('Look at the right-hand side: warning_count + 1. Read the value currently stored in warning_count: it is 1. Use that old value in the calculation. The stored value has not changed yet.','Lihat sebelah kanan: warning_count + 1. Baca nilai yang kini disimpan dalam warning_count: nilainya 1. Gunakan nilai lama itu dalam pengiraan. Nilai tersimpan belum berubah.','看右边的 warning_count + 1。读取 warning_count 当前存储的值：1。计算时使用这个旧值。存储的值还没有改变。'),calculation:'warning_count + 1 → 1 + 1',next:B('Calculate the right-hand side','Kira sebelah kanan','计算右边的表达式')},
 {line:2,value:'1',focus:'calculate',title:B('Line 2 · Calculate before storing','Baris 2 · Kira sebelum menyimpan','第2行 · 先计算，后存储'),note:B('Calculate 1 + 1. The result is 2, but we have not stored it yet. Notice that the memory still shows 1. The result of a calculation and the value currently stored are not always the same at this point.','Kira 1 + 1. Hasilnya 2, tetapi kita belum menyimpannya. Perhatikan bahawa memori masih menunjukkan 1. Pada tahap ini, hasil pengiraan dan nilai tersimpan belum sama.','计算 1 + 1，结果是 2，但还没有存储。注意存储区仍然显示 1。此时计算结果与当前存储的值不同。'),calculation:'1 + 1 = 2',next:B('Store the result','Simpan hasil','存储计算结果')},
 {line:2,value:'2',focus:'store',title:B('Line 2 · Replace the stored value','Baris 2 · Gantikan nilai tersimpan','第2行 · 替换存储的值'),note:B('Now assign the result 2 to warning_count on the left. The stored value changes from 1 to 2; the name stays the same. Line 2 is complete. There is no print() instruction, so this program has not displayed an output. These smaller steps explain what happens within one assignment.','Sekarang tugaskan hasil 2 kepada warning_count di sebelah kiri. Nilai tersimpan berubah daripada 1 kepada 2; nama kekal sama. Baris 2 selesai. Tiada arahan print(), jadi atur cara belum memaparkan output. Langkah kecil ini menerangkan perkara yang berlaku dalam satu penugasan.','现在把结果 2 赋给左边的 warning_count。存储的值从 1 变为 2，名称保持不变。第2行执行完毕。没有 print() 语句，所以程序没有显示输出。这些小步骤解释了一次赋值内部发生的过程。'),calculation:'warning_count: 1 → 2'}
 ]
};

const DATA_GUIDE={
 intro:B('Study the worked examples first. Learn what each part of an assignment means, how to name stored data clearly, and when a value should change or stay fixed. Then apply those ideas to five different practice questions.','Kaji contoh berpandu dahulu. Pelajari makna setiap bahagian penugasan, cara menamakan data dengan jelas dan bila nilai patut berubah atau kekal. Kemudian gunakan idea ini dalam lima soalan latihan yang berbeza.','先学习示例：了解赋值各部分的含义、如何清晰命名数据，以及数值何时应改变或保持固定。然后把这些方法应用到五道不同的练习题中。'),
 example:B('Worked example','Contoh berpandu','示例讲解'),practice:B('Your turn · five questions','Giliran anda · lima soalan','轮到你了 · 五道练习题'),
 anatomyTitle:B('1 · Read an assignment','1 · Baca penugasan','1 · 读懂赋值'),
 anatomyIntro:B('Sam’s helper has read four messages. This statement stores that count so the program can use it later.','Pembantu Sam telah membaca empat mesej. Pernyataan ini menyimpan bilangan itu supaya atur cara boleh menggunakannya kemudian.','Sam 的助手已读取四条消息。下面这条语句存储消息数量，方便程序稍后使用。'),
 parts:[
 {code:'messages_read',label:B('Identifier · the name','Pengecam · nama','标识符 · 名称'),explain:B('The name we use to refer to the stored value. It tells us that this value counts messages already read.','Nama yang digunakan untuk merujuk nilai tersimpan. Ia menjelaskan bahawa nilai ini mengira mesej yang sudah dibaca.','用于引用存储值的名称。它说明这个值表示已经读取的消息数量。')},
 {code:'=',label:B('Assignment · store the value','Penugasan · simpan nilai','赋值 · 存储值'),explain:B('Work out the right-hand side, then assign its value to the name on the left. This does not mean “compare”.','Kira sebelah kanan, kemudian tugaskan nilainya kepada nama di sebelah kiri. Ini bukan bermaksud “bandingkan”.','先求右边的值，再赋给左边的名称。这里不是“比较”的意思。')},
 {code:'4',label:B('Value · the data stored','Nilai · data yang disimpan','值 · 存储的数据'),explain:B('4 is the value. Its data type is integer (int), because it is a whole-number count. The name and the value are different things.','4 ialah nilai. Jenis datanya integer (int), kerana ia bilangan nombor bulat. Nama dan nilai ialah perkara berbeza.','4 是值，数据类型为整数（int），因为它是整数计数。名称和值不是同一回事。')}
 ],
 namesTitle:B('2 · Make the name useful to another person','2 · Jadikan nama berguna kepada orang lain','2 · 让别人读懂名称'),
 namesIntro:B('A valid identifier follows Python’s rules. A meaningful identifier also explains its purpose. Compare these three ways a beginner might try to store the number of messages read.','Pengecam sah mengikut peraturan Python. Pengecam bermakna juga menjelaskan tujuannya. Bandingkan tiga cara seorang pemula mungkin cuba menyimpan bilangan mesej yang dibaca.','有效的标识符符合 Python 规则。有意义的标识符还能说明用途。比较初学者可能用来存储已读消息数量的三种写法。'),
 names:[
 {kind:'invalid',label:B('Invalid · Python cannot use this name','Tidak sah · Python tidak boleh menggunakan nama ini','无效 · Python 不能使用这个名称'),code:'read messages = 4',why:B('The space splits the name into two words. Use an underscore to join words in one identifier.','Ruang memisahkan nama kepada dua perkataan. Gunakan garis bawah untuk menyambungkan perkataan dalam satu pengecam.','空格把名称分成两个词。可以用下划线把单词连接成一个标识符。')},
 {kind:'vague',label:B('Valid, but unclear','Sah, tetapi tidak jelas','有效，但不清楚'),code:'x = 4',why:B('Python accepts x, but a reader cannot tell what 4 counts. Is it messages, links or reminders?','Python menerima x, tetapi pembaca tidak tahu perkara yang dikira oleh 4. Adakah mesej, pautan atau peringatan?','Python 接受 x，但读者不知道 4 在数什么：消息、链接还是提醒？')},
 {kind:'clear',label:B('Valid and meaningful','Sah dan bermakna','有效且有意义'),code:'messages_read = 4',why:B('A reader can see that 4 is the number of messages already read. Clear names help you find the right value to update, explain the program and fix mistakes later.','Pembaca dapat melihat bahawa 4 ialah bilangan mesej yang sudah dibaca. Nama jelas membantu anda mencari nilai untuk dikemas kini, menerangkan atur cara dan membaiki kesilapan kemudian.','读者能看出 4 是已读消息数。清晰名称有助于找到要更新的值、解释程序，并在以后修正错误。')}
 ],
 namingRules:B('Name checklist: start with a letter or underscore; use letters, digits or underscores after that; do not use spaces or keywords such as if. Names are case-sensitive. Choose words that describe the data, and use the same spelling every time you refer to it.','Semakan nama: mulakan dengan huruf atau garis bawah; gunakan huruf, digit atau garis bawah selepas itu; jangan gunakan ruang atau kata kunci seperti if. Nama sensitif huruf besar/kecil. Pilih perkataan yang menerangkan data dan gunakan ejaan yang sama setiap kali merujuknya.','命名检查：以字母或下划线开头，之后可使用字母、数字或下划线；不要使用空格或 if 等关键字。名称区分大小写。选择能描述数据的词，并在每次引用时保持拼写一致。'),
 constantTitle:B('3 · Decide what may change and what stays fixed','3 · Tentukan perkara yang boleh berubah dan yang kekal','3 · 判断什么可变、什么固定'),
 constantIntro:B('This practice session lets Sam review up to eight messages. The chosen limit stays fixed during the session, while the number already read increases.','Sesi latihan ini membolehkan Sam menyemak sehingga lapan mesej. Had yang dipilih kekal sepanjang sesi, manakala bilangan yang sudah dibaca meningkat.','这个练习允许 Sam 最多查看八条消息。会话中上限保持固定，已读数量则逐渐增加。'),
 constantCode:['MAX_MESSAGES = 8','messages_read = 0','messages_read = messages_read + 1'],
 constantNotes:[
 B('Line 1 · MAX_MESSAGES is an intended constant. It stores the integer 8. A constant is a value we intend to keep fixed during a run. Uppercase words and underscores signal that intention in Python; Python does not prevent reassignment.','Baris 1 · MAX_MESSAGES ialah pemalar yang dimaksudkan. Ia menyimpan integer 8. Pemalar ialah nilai yang kita mahu kekalkan dalam satu larian. Huruf besar dan garis bawah menandakan niat itu dalam Python; Python tidak menghalang penugasan semula.','第1行 · MAX_MESSAGES 是预期常量，存储整数 8。常量指我们希望在一次运行中保持固定的值。Python 中用全大写和下划线表达这种意图，但语言本身不会阻止重新赋值。'),
 B('Line 2 · messages_read is a variable. It starts at the integer 0 because no messages have been read yet. Use a variable when the program needs to update the stored value.','Baris 2 · messages_read ialah pemboleh ubah. Ia bermula dengan integer 0 kerana belum ada mesej dibaca. Gunakan pemboleh ubah apabila atur cara perlu mengemas kini nilai tersimpan.','第2行 · messages_read 是变量。还没读消息，所以初始值是整数 0。如果程序需要更新存储值，就使用变量。'),
 B('Line 3 · One message has now been read. Read the old value 0, calculate 0 + 1, then store 1 in messages_read. MAX_MESSAGES remains 8. Both names store integers, but they have different purposes.','Baris 3 · Satu mesej kini sudah dibaca. Baca nilai lama 0, kira 0 + 1, kemudian simpan 1 dalam messages_read. MAX_MESSAGES kekal 8. Kedua-dua nama menyimpan integer, tetapi tujuannya berbeza.','第3行 · 现在读了一条消息。读取旧值 0，计算 0 + 1，再把 1 存入 messages_read。MAX_MESSAGES 仍为 8。两个名称都存储整数，但用途不同。')],
 typesTitle:B('4 · Choose a data type for the purpose','4 · Pilih jenis data mengikut tujuan','4 · 根据用途选择数据类型'),
 typesIntro:B('The value is the actual data; the data type tells us what kind of data it is. Look at the value and what the program needs to do with it.','Nilai ialah data sebenar; jenis data memberitahu kategori data itu. Lihat nilai dan perkara yang atur cara perlu lakukan dengannya.','值是实际的数据，数据类型说明它属于哪一类。既要看值本身，也要看程序要怎样使用它。'),
 types:[
 ['messages_read = 4','4','int',B('Integer · count whole messages. A count does not need a fractional part.','Integer · kira mesej penuh. Bilangan tidak memerlukan bahagian pecahan.','整数 · 计算完整消息的数量，不需要小数部分。')],
 ['review_minutes = 1.5','1.5','float',B('Real number · retain part of a minute. Python uses float for this example.','Nombor nyata · kekalkan bahagian satu minit. Python menggunakan float untuk contoh ini.','实数 · 保留不足一分钟的部分。这个 Python 示例使用 float。')],
 ['sender_name = "Alex"','"Alex"','str',B('String · keep a person’s name as text. Quotes mark the string literal.','Rentetan · simpan nama seseorang sebagai teks. Tanda petik menandakan literal rentetan.','字符串 · 将姓名保存为文本，引号标记字符串字面值。')],
 ['is_verified = False','False','bool',B('Boolean · store a True/False state. False has no quotes; "False" would be text instead.','Boolean · simpan keadaan True/False. False tiada tanda petik; "False" pula ialah teks.','布尔值 · 存储 True/False 状态。False 不加引号；"False" 则是文本。')]
 ],
 exampleName:B('Name','Nama','名称'),exampleValue:B('Value','Nilai','值'),exampleType:B('Data type','Jenis data','数据类型'),role:B('Variable or intended constant?','Pemboleh ubah atau pemalar yang dimaksudkan?','变量还是预期常量？'),
 variable:B('Variable · may be updated','Pemboleh ubah · boleh dikemas kini','变量 · 可以更新'),constant:B('Constant · intended to stay fixed','Pemalar · dimaksudkan kekal','常量 · 预期固定'),
 d4Title:B('4 · Help a beginner fix a variable assignment','4 · Bantu pemula membaiki penugasan pemboleh ubah','4 · 帮助初学者修正变量赋值'),
 d4Prompt:B('Sam’s checker has counted three links in a message. A beginner tried to store that count with the assignment below. The intended value is correct, but the variable name is invalid, so Python cannot run this statement.','Penyemak Sam telah mengira tiga pautan dalam satu mesej. Seorang pemula cuba menyimpan bilangan itu dengan penugasan di bawah. Nilai yang dimaksudkan betul, tetapi nama pemboleh ubah tidak sah, jadi Python tidak boleh menjalankan pernyataan ini.','Sam 的检查器数出一条消息中有三个链接。初学者试图用下面的赋值存储数量。要存的值是正确的，但变量名无效，所以 Python 无法执行这条语句。'),
 d4Steps:[B('Find the two naming-rule problems in the beginner’s code.','Cari dua masalah peraturan penamaan dalam kod pemula.','找出初学者代码中违反的两条命名规则。'),B('Replace the name with a valid, meaningful name for the number of links. Keep the integer value 3. Write the corrected assignment below.','Gantikan nama dengan nama sah dan bermakna bagi bilangan pautan. Kekalkan nilai integer 3. Tulis penugasan yang dibetulkan di bawah.','把名称改成有效且能说明链接数量的名称，保留整数值 3。在下方写出修正后的赋值。'),B('Explain both naming-rule fixes and what your new name tells another programmer.','Terangkan kedua-dua pembaikan peraturan nama dan perkara yang nama baharu beritahu pengatur cara lain.','解释如何修正两条命名规则，以及新名称能告诉其他程序员什么。')],
 d4CodeLabel:B('Your corrected Python assignment','Penugasan Python yang anda betulkan','你修正后的 Python 赋值'),
 d4AnswerLabel:B('Explain the two problems and why your new name is clearer.','Terangkan dua masalah dan mengapa nama baharu lebih jelas.','解释两个问题，以及新名称为什么更清晰。'),
 d5Title:B('5 · Explain the data in a reminder program','5 · Terangkan data dalam atur cara peringatan','5 · 解释提醒程序中的数据'),
 d5Prompt:B('Sam is now planning a reminder tool. During one session, the maximum number of reminders stays at three. The reminder count starts at zero and increases when a reminder is sent. The message text can be replaced when a new message is checked. Read each assignment on its own line.','Sam kini merancang alat peringatan. Dalam satu sesi, bilangan maksimum peringatan kekal tiga. Bilangan peringatan bermula sifar dan meningkat apabila peringatan dihantar. Teks mesej boleh diganti apabila mesej baharu disemak. Baca setiap penugasan pada barisnya sendiri.','Sam 正在规划提醒工具。一次会话中，提醒上限固定为三次。提醒计数从零开始，每发送一次提醒就增加。检查新消息时，可替换消息文本。逐行阅读以下赋值。'),
 d5Code:['MAX_REMINDERS = 3','reminder_count = 0','message_text = "Check the school portal"'],
 d5Steps:[B('For each line, enter the identifier (name), the starting value and its Python data type. Keep quotes around a string value.','Bagi setiap baris, masukkan pengecam (nama), nilai awal dan jenis data Python. Kekalkan tanda petik pada nilai rentetan.','为每一行填写标识符（名称）、初始值和 Python 数据类型。字符串值保留引号。'),B('Decide whether each value is intended to stay fixed or may be updated in the session described above.','Tentukan sama ada setiap nilai dimaksudkan kekal atau boleh dikemas kini dalam sesi yang diterangkan di atas.','根据上面的会话描述，判断每个值是预期固定，还是可以更新。'),B('Explain why the limit and the count have different roles, even though they use the same data type. Then justify the data type used for the message text.','Terangkan mengapa had dan bilangan mempunyai peranan berbeza walaupun jenis data sama. Kemudian justifikasikan jenis data untuk teks mesej.','解释为什么上限和计数虽然数据类型相同，作用却不同；再说明消息文本的数据类型为何合适。')],
 d5AnswerLabel:B('Explain your variable/constant choices and justify the message text’s data type.','Terangkan pilihan pemboleh ubah/pemalar dan justifikasikan jenis data teks mesej.','解释变量／常量的选择，并说明消息文本为何使用该类型。'),
 answerHint:B('Use the worked examples above as a method. Apply it to this new situation using your own names and explanations.','Gunakan contoh berpandu di atas sebagai kaedah. Gunakannya pada situasi baharu ini dengan nama dan penerangan anda sendiri.','借鉴上方示例的方法，把它应用到新情境中，使用自己的命名和解释。')
};
DATA.questions.find(q=>q.id==='d4').prompt=DATA_GUIDE.d4Prompt;
DATA.questions.find(q=>q.id==='d5').prompt=DATA_GUIDE.d5Prompt;

